function impacted(deps, changed) {
  const callers = {};
  for (const [m, list] of Object.entries(deps)) for (const d of list) (callers[d] = callers[d] || []).push(m);
  const seen = new Set(changed);
  const queue = [...changed];
  while (queue.length) {
    const x = queue.shift();
    for (const c of callers[x] || []) if (!seen.has(c)) { seen.add(c); queue.push(c); }
  }
  return [...seen].sort();
}
